import{_ as a,C as n,o as r,c as s,aj as e,G as i}from"./chunks/framework.BwH0p-pt.js";const f=JSON.parse('{"title":"Magic AI — Settings","description":"","frontmatter":{},"headers":[],"relativePath":"3.0/magic-ai/settings.md","filePath":"3.0/magic-ai/settings.md","lastUpdated":1785836850000}'),d={name:"3.0/magic-ai/settings.md"};function l(g,t,c,h,p,u){const o=n("ImagePopup");return r(),s("div",null,[t[0]||(t[0]=e('<h1 id="magic-ai-—-settings" tabindex="-1">Magic AI — Settings <a class="header-anchor" href="#magic-ai-—-settings" aria-label="Permalink to &quot;Magic AI — Settings&quot;">​</a></h1><blockquote><p><strong>Sidebar:</strong> Magic AI → <strong>Settings</strong><strong>URL:</strong> <code>/admin/magic-ai/settings</code> (the old <code>/admin/configuration/general/magic_ai</code> address redirects here)</p></blockquote><p>The <strong>Settings</strong> page is where you route each AI capability in UnoPim to a specific <strong>Platform</strong> and <strong>Model</strong>. This is also the home of the <strong>Agentic PIM</strong> controls — the token budget, approval mode, auto-enrichment toggle, and the Catalog Quality Monitor.</p><h2 id="what-does-this-page-do" tabindex="-1">What does this page do? <a class="header-anchor" href="#what-does-this-page-do" aria-label="Permalink to &quot;What does this page do?&quot;">​</a></h2><p>It contains four independent sections, one per capability:</p><ol><li><strong>Agentic PIM</strong> — configures the AI Agent Chat and its safety controls.</li><li><strong>Text Generation</strong> — powers the wand icons on product/category text fields.</li><li><strong>Image Generation</strong> — powers the wand icons on image and gallery attributes.</li><li><strong>Translation</strong> — configures auto-translation on product save, plus the bulk translation command.</li></ol><p>Because each section has its own Platform and Model dropdown, you can use <strong>different providers for different capabilities</strong> — for example, OpenAI for content generation and Gemini for translation.</p>',7)),i(o,{src:"/assets/3.0/images/magic-ai/magic-ai-settings.png",alt:"Magic AI Settings"}),t[1]||(t[1]=e('<h2 id="_1-agentic-pim" tabindex="-1">1. Agentic PIM <a class="header-anchor" href="#_1-agentic-pim" aria-label="Permalink to &quot;1. Agentic PIM&quot;">​</a></h2><p>Controls the conversational AI Agent and the background workflows it drives (auto-enrichment on product create, Catalog Quality Monitor, approval queue).</p><table tabindex="0"><thead><tr><th>Field</th><th>What it does</th></tr></thead><tbody><tr><td><strong>Enable AI Agent Chat</strong></td><td>Master switch for the AI chat widget. When off, the chat button is hidden and no one can converse with the agent.</td></tr><tr><td><strong>Open Chat Panel on Page Load</strong></td><td>When enabled, the chat panel opens automatically the first time an admin lands on a page.</td></tr><tr><td><strong>Max Agent Steps Per Turn</strong></td><td>How many tool calls the agent may chain for a single user message. The dropdown offers labeled presets: <strong>3 (Fast)</strong>, <strong>5 (Default)</strong>, <strong>10 (Thorough)</strong>, <strong>15 (Maximum)</strong>. Higher = more autonomy per turn; lower = tighter control and cheaper tokens.</td></tr><tr><td><strong>Daily Token Budget</strong></td><td>Global daily cap on AI Agent token spend (e.g., <code>500000</code>). Set to <code>0</code> for no limit. When the cap is hit, the agent replies with a budget-exhausted notice until midnight.</td></tr><tr><td><strong>Auto-Enrichment on Product Create</strong></td><td>When enabled, every new product is queued for AI enrichment — missing descriptions, SEO fields, etc. are filled in automatically.</td></tr><tr><td><strong>Catalog Quality Monitor</strong></td><td>Runs a scheduled AI sweep that reports on missing, thin, or inconsistent catalog data.</td></tr><tr><td><strong>Confidence Threshold</strong></td><td>Minimum confidence required before a proposed change is applied. Presets range from <strong>0.5 (Lenient)</strong> to <strong>0.9 (Very strict)</strong>; the default is <strong>0.7 (Balanced)</strong>. Below the threshold, the change is held for review.</td></tr><tr><td><strong>Change Approval Mode</strong></td><td>How the agent handles write operations: <strong>Confirm &amp; apply</strong> (default — the agent proposes values in chat, waits for your confirmation, then executes), <strong>Strict confirm</strong> (same, plus a verification after every change), or <strong>Suggest only</strong> (the agent describes changes but never executes them).</td></tr><tr><td><strong>Custom Agent Instructions</strong></td><td>Free-text instructions added to every agent conversation — use it for company conventions, naming rules, or tone.</td></tr></tbody></table><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>Start with <strong>Suggest only</strong> while you learn how the agent behaves on your catalog. Move to <strong>Confirm &amp; apply</strong> once you trust its output.</p></div><h2 id="_2-text-generation" tabindex="-1">2. Text Generation <a class="header-anchor" href="#_2-text-generation" aria-label="Permalink to &quot;2. Text Generation&quot;">​</a></h2><p>Controls the wand icons next to product and category text fields (Name, Short Description, Description, Meta Title, Meta Description, URL Key, etc.).</p><table tabindex="0"><thead><tr><th>Field</th><th>What it does</th></tr></thead><tbody><tr><td><strong>Enabled</strong></td><td>Toggle text generation on or off across the admin.</td></tr><tr><td><strong>Default Platform</strong></td><td>Which Platform serves text requests. Pick <strong><code>-- Use Default Platform --</code></strong> to follow the starred default, or override with a specific platform. Platforms marked with <code>*</code> in the dropdown are the current default.</td></tr><tr><td><strong>Default Model</strong></td><td>The model used for text, pulled from the models enabled on the chosen Platform.</td></tr></tbody></table><h2 id="_3-image-generation" tabindex="-1">3. Image Generation <a class="header-anchor" href="#_3-image-generation" aria-label="Permalink to &quot;3. Image Generation&quot;">​</a></h2><p>Controls the wand icons on Image and Gallery attributes. Only Platforms whose provider supports image generation (OpenAI / DALL-E, Gemini, xAI) appear here.</p><table tabindex="0"><thead><tr><th>Field</th><th>What it does</th></tr></thead><tbody><tr><td><strong>Enabled</strong></td><td>Toggle image generation on or off.</td></tr><tr><td><strong>Default Platform</strong></td><td>An image-capable Platform. Pick <strong><code>-- Use Default Platform --</code></strong> to follow the starred default; <code>*</code> in the dropdown marks the current default.</td></tr><tr><td><strong>Default Model</strong></td><td>The specific image model (e.g., <code>dall-e-3</code>).</td></tr></tbody></table><h2 id="_4-translation" tabindex="-1">4. Translation <a class="header-anchor" href="#_4-translation" aria-label="Permalink to &quot;4. Translation&quot;">​</a></h2><p>Controls auto-translation on product save and the AI-powered bulk translation command. Because translation tends to be high-volume, you can assign it a different (often cheaper/faster) Platform.</p><table tabindex="0"><thead><tr><th>Field</th><th>What it does</th></tr></thead><tbody><tr><td><strong>Enabled</strong></td><td>Turn AI-powered translation on or off.</td></tr><tr><td><strong>Default Platform</strong></td><td>The Platform used for translation requests. Pick <strong><code>-- Use Default Platform --</code></strong> to follow the starred default; <code>*</code> in the dropdown marks the current default.</td></tr><tr><td><strong>Translation Model</strong></td><td>The specific model used for translation — independent of the text-generation model.</td></tr><tr><td><strong>Replace Existing Value</strong></td><td>On: re-translating overwrites existing locale values. Off: only empty locale fields are filled, preserving manual translations.</td></tr><tr><td><strong>Source Channel</strong></td><td>The channel whose values serve as the source-of-truth.</td></tr><tr><td><strong>Target Channel</strong></td><td>The channel that receives the translated values.</td></tr><tr><td><strong>Source Locale</strong></td><td>The locale to translate from (e.g., <code>en_US</code>).</td></tr><tr><td><strong>Target Locales</strong></td><td>Multi-select — every locale to auto-populate.</td></tr></tbody></table><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>You can assign a different (potentially cheaper or faster) AI provider specifically for translations, keeping your premium provider for content generation.</p></div><p>Click <strong>Save Configuration</strong> in the page header to apply all changes. Settings take effect immediately — no restart required. Your selections, including the chosen <strong>Target Locales</strong>, are kept and shown again the next time you open the page.</p><h2 id="where-the-values-come-from" tabindex="-1">Where the values come from <a class="header-anchor" href="#where-the-values-come-from" aria-label="Permalink to &quot;Where the values come from&quot;">​</a></h2><p>The Platform / Model dropdowns on this page are populated entirely from the <strong><a href="./platforms.html">Platforms</a></strong> page. If a Platform isn&#39;t listed, either (a) it&#39;s disabled, (b) its provider doesn&#39;t support the capability (e.g., Ollama doesn&#39;t show up in Image Generation), or (c) you haven&#39;t registered it yet. If no platform exists at all, the page tells you so and points you to the Platforms page to add your first provider.</p><p>Similarly, the <strong>Translation</strong> section&#39;s Source / Target Channel and Locale dropdowns are populated from your channel and locale configuration (see <strong>Settings → Channels</strong> and <strong>Settings → Locales</strong>).</p>',18))])}const b=a(d,[["render",l]]);export{f as __pageData,b as default};
